"""Brahmagupta family product with a running unit-twist normal form."""

from __future__ import annotations

from math import isqrt
from typing import List, Sequence, Tuple

Triple = Tuple[int, int, int]

ONE: Triple = (1, 0, 1)


def mul(t: Triple, s: Triple) -> Triple:
    """Brahmagupta-Fibonacci product: Gaussian multiplication on legs, product on hypotenuses."""
    a, b, c = t
    a2, b2, c2 = s
    return (a * a2 - b * b2, a * b2 + b * a2, c * c2)


def family_product(family: Sequence[Triple]) -> Triple:
    """Left-to-right accumulation of the Brahmagupta product; O(n) multiplications."""
    acc: Triple = ONE
    for t in family:
        acc = mul(acc, t)
    return acc


def unit_normal_form(t: Triple) -> Triple:
    """Rotate a triple by a power of the quarter turn into the closed first quadrant.

    Every triple has exactly four rotates (multiply by 1, i, -1, -i); this picks the one
    with a >= 0 and b > 0, or a > 0 and b == 0, giving a canonical representative of the
    orbit of the unit group Z/4.
    """
    a, b, c = t
    if (a, b) == (0, 0):
        return t
    for _ in range(4):
        if (a > 0 and b >= 0) and not (a == 0):
            return (a, b, c)
        a, b = -b, a  # multiplication by i
    return (a, b, c)


def product_up_to_units(family: Sequence[Triple]) -> Triple:
    """The product, reported in unit normal form: the true invariant of the family."""
    return unit_normal_form(family_product(family))


def hypotenuse_profile(family: Sequence[Triple]) -> List[int]:
    """The sorted multiset of hypotenuses, the natural extra invariant of a family."""
    return sorted(t[2] for t in family)


def verify_triple(t: Triple) -> bool:
    """Check a^2 + b^2 = c^2 with c >= 0."""
    a, b, c = t
    return c >= 0 and a * a + b * b == c * c and isqrt(c * c) == c

