function BALANCED-DIGIT(v, B):
    r <- v mod B                            # in [0, B)
    if 2r > B: r <- r - B
    return r                                # unique r with 2|r| < B

function DECODE(B, (re, im), n):
    family <- empty list
    for j = 0 to n-1:
        a <- BALANCED-DIGIT(re, B);  b <- BALANCED-DIGIT(im, B)
        append the triple with legs (a, b) to family
        (re, im) <- ((re - a)/B,  (im - b)/B)
    assert (re, im) = (0, 0)
    return family

