"""Positional (base-B) aggregation of a family of Pythagorean triples in Z[i], and its
exact inverse by balanced digit extraction."""

from __future__ import annotations

from math import isqrt
from typing import List, Sequence, Tuple

Triple = Tuple[int, int, int]
Gauss = Tuple[int, int]  # (real, imaginary)


def make_triple(a: int, b: int) -> Triple:
    """Complete a leg pair of square norm to a Pythagorean triple with c >= 0."""
    n = a * a + b * b
    c = isqrt(n)
    if c * c != n:
        raise ValueError(f"legs ({a}, {b}) do not have square norm")
    return (a, b, c)


def admissible_base(family: Sequence[Triple]) -> int:
    """The smallest odd base B with 2|a|, 2|b| < B for every member: B = 2M + 1."""
    m = max((max(abs(t[0]), abs(t[1])) for t in family), default=0)
    return 2 * m + 1


def encode(base: int, family: Sequence[Triple]) -> Gauss:
    """Horner evaluation of the Gaussian polynomial sum_j z_j B^j; O(n) operations."""
    re, im = 0, 0
    for t in reversed(family):
        re, im = re * base + t[0], im * base + t[1]
    return (re, im)


def balanced_digit(value: int, base: int) -> int:
    """The unique r congruent to value mod base with 2|r| < base (base odd)."""
    r = value % base
    if 2 * r > base:
        r -= base
    return r


def decode(base: int, agg: Gauss, length: int) -> List[Triple]:
    """Recover the unique balanced family of the given length from its aggregate."""
    re, im = agg
    out: List[Triple] = []
    for _ in range(length):
        a, b = balanced_digit(re, base), balanced_digit(im, base)
        out.append(make_triple(a, b))
        re, im = (re - a) // base, (im - b) // base
    if (re, im) != (0, 0):
        raise ValueError("aggregate does not come from a balanced family of this length")
    return out


def round_trip(family: Sequence[Triple]) -> bool:
    """Encode with the smallest admissible base and check exact recovery."""
    base = admissible_base(family)
    return decode(base, encode(base, family), len(family)) == list(family)
